// TimedKind says what a TimedEvent is the time of. The untranslated
// description (TimedEvent.Desc) remains the translation key and the stable
// identifier; the kind is what code should switch on.
type TimedKind int

const (
	// TimedOther is the zero TimedKind: a timed event of no particular kind.
	TimedOther TimedKind = iota
	// CandleLighting is candle-lighting before Shabbat or a holiday.
	CandleLighting
	// Havdalah is the end of Shabbat or a holiday.
	Havdalah
	// ChanukahCandles is the lighting of the Chanukah candles; the event's
	// description is the holiday's ("Chanukah: 3 Candles").
	ChanukahCandles
	// FastBegins is the start of a fast.
	FastBegins
	// FastEnds is the end of a fast.
	FastEnds
	// FinishChametz is the latest time to eat chametz on Erev Pesach.
	FinishChametz
	// BiurChametz is the latest time to burn chametz before Pesach.
	BiurChametz
	// KiddushLevana is the latest time to recite Kiddush Levana.
	KiddushLevana
	// Zman is one of the daily halachic times of Options.DailyZmanim.
	Zman
)

var timedKindNames = [...]string{
	TimedOther:      "TimedOther",
	CandleLighting:  "CandleLighting",
	Havdalah:        "Havdalah",
	ChanukahCandles: "ChanukahCandles",
	FastBegins:      "FastBegins",
	FastEnds:        "FastEnds",
	FinishChametz:   "FinishChametz",
	BiurChametz:     "BiurChametz",
	KiddushLevana:   "KiddushLevana",
	Zman:            "Zman",
}

// String returns the name of the constant, e.g. "CandleLighting".
func (k TimedKind) String() string {
	if k < 0 || int(k) >= len(timedKindNames) {
		return "TimedKind(" + strconv.Itoa(int(k)) + ")"
	}
	return timedKindNames[k]
}

// Untranslated descriptions of the timed events whose description follows
// from their kind.
const (
	descCandleLighting = "Candle lighting"
	descHavdalah       = "Havdalah"
	descFastBegins     = "Fast begins"
	descFastEnds       = "Fast ends"
	descFinishChametz  = "Finish eating chametz"
	descBiurChametz    = "Biur Chametz"
)

// timedKindOf is the kind of a timed event built from a description and
// flags alone, as NewTimedEvent's callers do.
func timedKindOf(desc string, flags event.Flags) TimedKind {
	switch desc {
	case descCandleLighting:
		return CandleLighting
	case descHavdalah:
		return Havdalah
	case descFastBegins:
		return FastBegins
	case descFastEnds:
		return FastEnds
	case descFinishChametz:
		return FinishChametz
	case descBiurChametz:
		return BiurChametz
	case latestKiddushLevana:
		return KiddushLevana
	}
	switch {
	case flags.Has(event.KiddushLevana):
		return KiddushLevana
	case flags == event.Zmanim:
		return Zman
	}
	return TimedOther
}

// TimedEvent is an event that occurs at a clock time: candle-lighting,
// Havdalah, the start or end of a fast, Chanukah candle-lighting, the
// deadlines for chametz on Erev Pesach, a daily zman. It satisfies
// event.Timed and event.Linked.
type TimedEvent struct {
	date         hdate.HDate
	desc         string
	flags        event.Flags
	emoji        string
	kind         TimedKind
	eventTime    time.Time
	linked       event.CalEvent
	sunsetOffset int
	clock        clock
	// chagReading is the untranslated name of the festival reading that
	// displaces the weekly portion, for erev-Shabbat candle-lighting in a
	// festival week (see Memo).
	chagReading string
	// ChanukahDay is the day of Chanukah (1-8) whose candles the event
	// lights, or 0 for every other event.
	ChanukahDay int
}

var (
	_ event.Timed         = TimedEvent{}
	_ event.Linked        = TimedEvent{}
	_ event.Memoer        = TimedEvent{}
	_ event.BriefRenderer = TimedEvent{}
)

// TimedKindOf returns the kind of a timed event generated by this package
// (a TimedEvent or a KiddushLevanaEvent), and false for any other event.
func TimedKindOf(ev event.CalEvent) (TimedKind, bool) {
	switch e := ev.(type) {
	case TimedEvent:
		return e.kind, true
	case KiddushLevanaEvent:
		return KiddushLevana, true
	}
	return TimedOther, false
}

// isChanukah reports whether ev is the candle-lighting of a night of
// Chanukah, which stands for the holiday itself.
func (ev TimedEvent) isChanukah() bool {
	return ev.flags.Has(event.ChanukahCandles) && ev.linked != nil
}

// Kind returns what the event is the time of.
func (ev TimedEvent) Kind() TimedKind {
	return ev.kind
}

// Time returns the time at which the event occurs, in the time zone of the
// calendar's location.
func (ev TimedEvent) Time() time.Time {
	return ev.eventTime
}

// LinkedEvent returns the event this one belongs to, or nil if there is
// none: the holiday whose candles are lit, whose end Havdalah marks or
// whose fast begins or ends, or the parsha of the Shabbat that erev-Shabbat
// candle-lighting begins.
func (ev TimedEvent) LinkedEvent() event.CalEvent {
	return ev.linked
}

// Memo returns, for erev-Shabbat candle-lighting, the coming Shabbat's Torah
// portion ("Parashat Vayera"), or the festival reading that displaces it
// ("Pesach I"). Other timed events have no memo of their own.
func (ev TimedEvent) Memo(locale string) string {
	if ev.kind != CandleLighting {
		return ""
	}
	if ev.chagReading != "" {
		s, _ := locales.LookupTranslation(ev.chagReading, locale)
		return s
	}
	if ev.linked != nil && ev.linked.Flags() == event.ParshaHashavua {
		return ev.linked.Render(locale)
	}
	return ""
}

// Desc returns the untranslated description, e.g. "Candle lighting" or
// "Chanukah: 3 Candles".
func (ev TimedEvent) Desc() string {
	return ev.desc
}

// NewTimedEvent constructs a timed event, or the zero TimedEvent if t is the
// zero time. Its kind follows from desc ("Candle lighting", "Havdalah",
// "Fast begins", ...) or, for a daily zman, from flags. opts chooses the
// clock format its time is rendered in (see ReformatTimeStr) and may be nil;
// the event keeps that format, not a reference to opts.
func NewTimedEvent(hd hdate.HDate, desc string, flags event.Flags, t time.Time,
	sunsetOffset int, linkedEvent event.CalEvent, opts *Options) TimedEvent {
	return newTimedEvent(hd, timedKindOf(desc, flags), desc, flags, t, sunsetOffset, linkedEvent, clockFor(opts))
}

func newTimedEvent(hd hdate.HDate, kind TimedKind, desc string, flags event.Flags, t time.Time,
	sunsetOffset int, linkedEvent event.CalEvent, clock clock) TimedEvent {
	if t.IsZero() {
		return TimedEvent{}
	}
	var emoji string
	switch kind {
	case CandleLighting:
		emoji = "🕯️"
	case Havdalah:
		emoji = "✨"
	}
	// Round to the nearest minute, matching @hebcal/core's TimedEvent
	// (this.eventTime = Zmanim.roundTime(eventTime)). SunsetOffset already
	// yields a whole minute, so in practice this only affects the degree-based
	// tzeit times (havdalah, fast begin/end, chametz). The Zmanim daily-times
	// feature has no @hebcal/core equivalent and keeps its unrounded times.
	if flags != event.Zmanim {
		t = roundToMinute(t)
	}
	return TimedEvent{
		date:         hd,
		desc:         desc,
		flags:        flags,
		emoji:        emoji,
		kind:         kind,
		eventTime:    t,
		linked:       linkedEvent,
		clock:        clock,
		sunsetOffset: sunsetOffset,
	}
}

// roundToMinute rounds t to the nearest minute (>= 30 seconds rounds up),
// matching @hebcal/core Zmanim.roundTime.
func roundToMinute(t time.Time) time.Time {
	if t.IsZero() {
		return t
	}
	if t.Second() == 0 && t.Nanosecond() == 0 {
		return t
	}
	year, month, day := t.Date()
	hour, min, sec := t.Clock()
	if sec >= 30 {
		min++
	}
	return time.Date(year, month, day, hour, min, 0, 0, t.Location())
}

func (ev TimedEvent) Date() hdate.HDate {
	return ev.date
}

// Render returns the translated description and the time, e.g. "Candle
// lighting: 7:13pm".
func (ev TimedEvent) Render(locale string) string {
	timeStr := ev.clock.formatTime(ev.eventTime)
	return fmt.Sprintf("%s: %s", ev.RenderBrief(locale), timeStr)
}

// RenderBrief returns the translated description without its time, e.g.
// "Candle lighting" or "Havdalah (50 min)".
func (ev TimedEvent) RenderBrief(locale string) string {
	desc, _ := locales.LookupTranslation(ev.desc, locale)
	if ev.kind == Havdalah && ev.sunsetOffset != 0 {
		minStr, _ := locales.LookupTranslation("min", locale)
		desc = fmt.Sprintf("%s (%d %s)", desc, ev.sunsetOffset, minStr)
	}
	return desc
}

func (ev TimedEvent) Flags() event.Flags {
	return ev.flags
}

func (ev TimedEvent) Emoji() string {
	return ev.emoji
}

// Basename returns the description, or for Chanukah candle-lighting the
// holiday's basename ("Chanukah").
func (ev TimedEvent) Basename() string {
	if ev.isChanukah() {
		return ev.linked.Basename()
	}
	return ev.desc
}

// Categories returns the category and sub-categories for a timed event,
// keyed by its kind, matching TimedEvent.getCategories() in @hebcal/core.
//
// Chanukah candle-lighting takes the holiday's categories.
func (ev TimedEvent) Categories() []string {
	if ev.isChanukah() {
		return ev.linked.Categories()
	}
	switch ev.kind {
	case CandleLighting:
		return []string{"candles"}
	case Havdalah:
		return []string{"havdalah"}
	case FastBegins, FastEnds:
		return []string{"zmanim", "fast"}
	case FinishChametz:
		return []string{"zmanim", "achilasChametz"}
	case BiurChametz:
		return []string{"zmanim", "biurChametz"}
	}
	return []string{"unknown"}
}

// newZmanim builds a Zmanim for the Gregorian date of hd at the options'
// Location, honoring opts.UseElevation so that sunrise/sunset-based times
// account for the location's elevation when requested. Degree-based zmanim are
// never affected by elevation.
//
// newCalConfig has already checked that the location can be used, so
// constructing the Zmanim cannot fail here.
func newZmanim(hd hdate.HDate, opts *calConfig) zmanim.Zmanim {
	year, month, day := hd.Greg()
	gregDate := time.Date(year, month, day, 0, 0, 0, 0, time.UTC)
	z := zmanim.MustNew(opts.Location, gregDate)
	z.UseElevation = opts.UseElevation
	return z
}

func makeCandleEvent(hd hdate.HDate, opts *calConfig, ev event.CalEvent) TimedEvent {
	havdalahTitle := false
	useHavdalahOffset := false
	dow := hd.Weekday()
	if dow == time.Saturday {
		useHavdalahOffset = true
	}
	flags := event.LightCandles
	if ev != nil {
		flags = ev.Flags()
		if dow != time.Friday {
			if flags.HasAny(event.LightCandlesTzeis | event.ChanukahCandles) {
				useHavdalahOffset = true
			} else if flags.Has(event.YomTovEnds) {
				havdalahTitle = true
				useHavdalahOffset = true
			}
		}
	} else if dow == time.Saturday {
		havdalahTitle = true
		flags = event.LightCandlesTzeis
	}
	// A zero Havdalah offset means tzeit. A zero candle-lighting offset
	// means sunset itself (CandleLightingAtSunset).
	offset := opts.CandleLightingMins
	if useHavdalahOffset {
		offset = opts.HavdalahMins
	}
	z := newZmanim(hd, opts)
	var eventTime time.Time
	if useHavdalahOffset && offset == 0 {
		eventTime = z.Tzeit(opts.HavdalahDeg)
	} else {
		eventTime = z.SunsetOffset(offset, true)
	}
	if eventTime.IsZero() {
		return TimedEvent{} // no sunset
	}
	kind, desc := CandleLighting, descCandleLighting
	if havdalahTitle {
		kind, desc = Havdalah, descHavdalah
	} else if !flags.Has(event.ChanukahCandles) {
		// Exactly one of the two candle-lighting flags, chosen by how the
		// time was computed: LightCandles for minutes before sunset
		// (Shabbat or the start of a chag), LightCandlesTzeis for
		// nightfall / Havdalah time (the second night of Yom Tov, or a chag
		// that begins Saturday night). Chanukah keeps its own flags: its
		// Friday and Saturday events reuse this event as the Chanukah event.
		if useHavdalahOffset {
			flags = flags.Without(event.LightCandles).With(event.LightCandlesTzeis)
		} else {
			flags = flags.Without(event.LightCandlesTzeis).With(event.LightCandles)
		}
	}
	return newTimedEvent(hd, kind, desc, flags, eventTime, offset, ev, opts.clock)
}

// makeChanukahCandleLighting returns the Chanukah event ev with the time its
// candles are lit: at regular candle-lighting time on Friday, at Havdalah
// time on Saturday night, and at dusk on other days.
func makeChanukahCandleLighting(ev event.HolidayEvent, opts *calConfig) TimedEvent {
	hd := ev.Date()
	dow := hd.Weekday()
	if dow == time.Friday || dow == time.Saturday {
		timedEv := makeCandleEvent(hd, opts, ev)
		if (timedEv == TimedEvent{}) {
			return timedEv // no sunset
		}
		timedEv.kind = ChanukahCandles
		timedEv.desc = ev.Desc()
		timedEv.emoji = ev.Emoji()
		timedEv.ChanukahDay = ev.ChanukahDay
		return timedEv
	}
	z := newZmanim(hd, opts)
	candleLightingTime := z.BeinHashmashos()
	if candleLightingTime.IsZero() {
		return TimedEvent{} // no sunset
	}
	return TimedEvent{
		date:  ev.Date(),
		desc:  ev.Desc(),
		flags: ev.Flags(),
		emoji: ev.Emoji(),
		kind:  ChanukahCandles,
		// Round to the nearest minute, as NewTimedEvent does and as
		// @hebcal/core's TimedChanukahEvent does with Zmanim.roundTime.
		eventTime:   roundToMinute(candleLightingTime),
		linked:      ev,
		clock:       opts.clock,
		ChanukahDay: ev.ChanukahDay,
	}
}

func makeFastStartEnd(ev event.CalEvent, opts *calConfig) (TimedEvent, TimedEvent) {
	hd := ev.Date()
	z := newZmanim(hd, opts)
	desc := ev.Desc()
	flags := ev.Flags()
	var startEvent, endEvent TimedEvent
	if desc == "Erev Tish'a B'Av" {
		sunset := z.Sunset()
		startEvent = newTimedEvent(hd, FastBegins, descFastBegins, flags, sunset, 0, ev, opts.clock)
	} else if strings.HasPrefix(desc, "Tish'a B'Av") {
		endEvent = newTimedEvent(hd, FastEnds, descFastEnds, flags, fastEndTime(&z, true, opts), 0, ev, opts.clock)
	} else {
		startEvent = newTimedEvent(hd, FastBegins, descFastBegins, flags, fastStartTime(&z, opts), 0, ev, opts.clock)
		if hd.Weekday() != time.Friday && !(hd.Day() == 14 && hd.Month() == hdate.Nisan) {
			endEvent = newTimedEvent(hd, FastEnds, descFastEnds, flags, fastEndTime(&z, false, opts), 0, ev, opts.clock)
		}
	}
	return startEvent, endEvent
}

const (
	// alot16Point1 is Alot HaShachar, the default start of a minor fast.
	alot16Point1 = 16.1
	// tzeitTucazinsky is the default end of Tish'a B'Av, 6.45 degrees as
	// calculated by Rabbi Yechiel Michel Tucazinsky.
	tzeitTucazinsky = 6.45
	// minorFastEndMinutesIL is the default end of a minor fast in Israel, 15
	// minutes after sunset (Rabbi Deblitzky's practice).
	minorFastEndMinutesIL = 15
)

// fastStartTime is when a minor fast begins: opts.FastStartMins before
// sunrise, when the sun is opts.FastStartDeg below the horizon, or at Alot
// HaShachar.
func fastStartTime(z *zmanim.Zmanim, opts *calConfig) time.Time {
	if opts.FastStartMins != 0 {
		return z.SunriseOffset(-opts.FastStartMins, true)
	}
	deg := opts.FastStartDeg
	if deg == 0 {
		deg = alot16Point1
	}
	return z.TimeAtAngle(deg, true)
}

// fastEndTime is when a fast ends. Tish'a B'Av ends opts.TishaBavEndMins
// after sunset, at tzeit opts.TishaBavEndDeg, or at tzeit 6.45 degrees, and
// ignores opts.IL. A minor fast ends opts.FastEndMins after sunset, at tzeit
// opts.FastEndDeg, or else 15 minutes after sunset in Israel and at tzeit
// 7.083 degrees elsewhere.
func fastEndTime(z *zmanim.Zmanim, isTishaBav bool, opts *calConfig) time.Time {
	if isTishaBav {
		if opts.TishaBavEndMins != 0 {
			return z.SunsetOffset(opts.TishaBavEndMins, true)
		}
		deg := opts.TishaBavEndDeg
		if deg == 0 {
			deg = tzeitTucazinsky
		}
		return z.Tzeit(deg)
	}
	if opts.FastEndMins != 0 {
		return z.SunsetOffset(opts.FastEndMins, true)
	}
	if opts.FastEndDeg != 0 {
		return z.Tzeit(opts.FastEndDeg)
	}
	if opts.IL {
		return z.SunsetOffset(minorFastEndMinutesIL, true)
	}
	return z.Tzeit(zmanim.Tzeit3MediumStars)
}

// makeErevPesachChametz returns the "Finish eating chametz" (sof zman achilat
// chametz) and "Biur Chametz" (sof zman biur chametz) events for Erev Pesach.
// It is modeled on hebcal-es6's makeErevPesachChametzEvents.
//
// Sof zman achilat chametz is the same as sof zman tefilla (Gra, sunrise plus 4
// halachic hours); sof zman biur chametz is one halachic hour later. When Erev
// Pesach falls on Shabbat, chametz cannot be burned on Shabbat, so the Biur
// Chametz event is emitted on the Friday before instead (see makeBiurChametz)
// and is omitted here.
func makeErevPesachChametz(ev event.CalEvent, opts *calConfig) []event.CalEvent {
	hd := ev.Date()
	z := newZmanim(hd, opts)
	events := make([]event.CalEvent, 0, 2)
	achilas := z.SofZmanAchilasChametz()
	if achilas.IsZero() {
		return events
	}
	achilasEv := newTimedEvent(hd, FinishChametz, descFinishChametz, 0, achilas, 0, nil, opts.clock)
	achilasEv.emoji = "🍞"
	events = append(events, achilasEv)
	if hd.Weekday() != time.Saturday {
		if biurEv := makeBiurChametz(hd, opts); (biurEv != TimedEvent{}) {
			events = append(events, biurEv)
		}
	}
	return events
}

// makeBiurChametz returns the "Biur Chametz" (sof zman biur chametz) event for
// the given day, or an empty TimedEvent if the sun does not rise/set.
func makeBiurChametz(hd hdate.HDate, opts *calConfig) TimedEvent {
	z := newZmanim(hd, opts)
	biur := z.SofZmanBiurChametz()
	if biur.IsZero() {
		return TimedEvent{}
	}
	biurEv := newTimedEvent(hd, BiurChametz, descBiurChametz, 0, biur, 0, nil, opts.clock)
	biurEv.emoji = "🔥"
	return biurEv
}

type riseSetEvent struct {
	date    hdate.HDate
	sunrise time.Time
	sunset  time.Time
	clock   clock
}

func newRiseSetEvent(hd hdate.HDate, opts *calConfig) riseSetEvent {
	z := newZmanim(hd, opts)
	return riseSetEvent{date: hd, sunrise: z.Sunrise(), sunset: z.Sunset(), clock: opts.clock}
}

func (ev riseSetEvent) Date() hdate.HDate {
	return ev.date
}

func (ev riseSetEvent) Render(locale string) string {
	riseStr := ev.clock.formatTime(ev.sunrise)
	setStr := ev.clock.formatTime(ev.sunset)
	return fmt.Sprintf("Sunrise: %s; Sunset %s", riseStr, setStr)
}

func (ev riseSetEvent) Flags() event.Flags {
	return event.Zmanim
}

func (ev riseSetEvent) Emoji() string {
	return ""
}

func (ev riseSetEvent) Basename() string {
	return ev.Render("en")
}

func (ev riseSetEvent) Desc() string {
	return ev.Basename()
}

func (ev riseSetEvent) URL() string {
	return ""
}

func (ev riseSetEvent) Categories() []string {
	return []string{"zmanim"}
}

func dailyZemanim(date hdate.HDate, opts *calConfig) []event.CalEvent {
	z := newZmanim(date, opts)
	times := []struct {
		desc string
		t    time.Time
	}{
		{"Alot HaShachar", z.AlotHaShachar()},
		{"Misheyakir", z.Misheyakir()},
		{"Misheyakir Machmir", z.MisheyakirMachmir()},
		{"Sunrise", z.Sunrise()},
		{"Kriat Shema, sof zeman (MGA)", z.SofZmanShmaMGA()},
		{"Kriat Shema, sof zeman (GRA)", z.SofZmanShma()},
		{"Tefilah, sof zeman (MGA)", z.SofZmanTfillaMGA()},
		{"Tefilah, sof zeman (GRA)", z.SofZmanTfilla()},
		{"Chatzot HaYom", z.Chatzot()},
		{"Mincha Gedolah", z.MinchaGedola()},
		{"Mincha Ketanah", z.MinchaKetana()},
		{"Plag HaMincha", z.PlagHaMincha()},
		{"Sunset", z.Sunset()},
		{"Bein HaShemashot", z.BeinHashmashos()},
		{"Tzeit HaKochavim", z.Tzeit(zmanim.Tzeit3SmallStars)},
	}
	events := make([]event.CalEvent, 0, len(times))
	for _, zman := range times {
		if !zman.t.IsZero() {
			ev := newTimedEvent(date, Zman, zman.desc, event.Zmanim, zman.t, 0, nil, opts.clock)
			events = append(events, ev)
		}
	}
	return events
}

// URL returns the Chanukah page for Chanukah candle lighting, and "" for
// every other timed event.
//
// Only Chanukah is treated as linkable. Candle lighting before Pesach also
// carries a LinkedEvent, but a clock time is not itself an observance with a
// page, and following every link would attach a holiday URL to each Friday
// evening in the calendar.
func (ev TimedEvent) URL() string {
	if !ev.isChanukah() {
		return ""
	}
	return ev.linked.URL()
}
